mapper.select:
select DELIVERY_NOTE_ID, ORGANIZATION_ID, FULL_PATH_ID, VENDOR_ID, DELIVERY_NUMBER, DELIVERY_DATE, EXPECTED_ARRIVAL_DATE, OLD_DELIVERY_NOTE_ID, DELIVERY_NOTE_STATUS, COMMENTS, ORGANIZATION_NAME, VENDOR_CODE, VENDOR_NAME, SUBMITTED_ID, SUBMITTED_BY, SUBMITTED_TIME, CREATED_ID, CREATED_BY, CREATION_DATE, CREATED_BY_IP, CREATED_FULL_NAME, LAST_UPDATED_ID, LAST_UPDATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY_IP, LAST_UPDATED_FULL_NAME, TENANT_ID, VERSION, ORGANIZATION_CODE, CONTACT_PEOPLE, CONTACT_NUMBER, ORG_ID, ORG_CODE, ORG_NAME, CEEA_DELIVERY_PLACE, DATA_SOURCE, DELIVERY_TYPE, CREATED_BY_CODE, CEEA_CONSIGN_TYPE, CEEA_DELIVERY_SYSTEM, PURCHASE_CONFIRM_STATUS, IF_CREATE_DELIVERY_APPOINTMENT, RECEIVED_FACTORY_ID, RECEIVED_FACTORY, ORDER_SOURCE, EXT_STATUS, EXT_VENDOR_CONTACTS, EXT_VENDOR_PHONE, EXT_EXPRESS_TYPE, EXT_EXPRESS_NO, EXT_EXPRESS_MAN, EXT_EXPRESS_PHONE, EXT_DEPARTMENT_ID, EXT_DEPARTMENT_CODE, EXT_DEPARTMENT_NAME, EXT_APPLICANT_NAME, EXT_APPLICANT_CODE, EXT_APPLY_DATE, EXT_UN_TAX_AMOUNT, EXT_IN_TAX_AMOUNT, EXT_CURRENCY_ID, EXT_CURRENCY_CODE, EXT_CURRENCY_NAME, EXT_RECEIVE_CONTACT, EXT_RECEIVE_TELEPHONE, EXT_PURCHASER_NO, EXT_PURCHASER_ID, EXT_PURCHASER_NAME, EXT_PURCHASER_ORG_NAME, EXT_PURCHASER_PHONE, EXT_PURCHASER_EMAIL, EXT_JD_ORDER_ID from scc_sc_delivery_note
AND DELIVERY_NUMBER=#{deliveryNumber}
AND DELIVERY_NOTE_STATUS=#{deliveryNoteStatus}
AND ORG_NAME=#{orgName}
AND ORG_ID=#{orgId}
AND EXT_PURCHASER_NO=#{extPurchaserNo}
AND VENDOR_NAME=#{vendorName}
AND DELIVERY_DATE between #{beginDate} and #{endDate}
